# GPU Scene rendering fixture. Use with --map and a fixed --gpu-normal-scene view.
# No identity: keep the Campaign content policy while replacing its spatial map.
map version=1 units=rfu
world min_x=-7000 max_x=7000 min_z=-2000 max_z=9000 room_limit=10000

